/* Helpers (no dependencies):
     C.byNpsn(npsn)   one contact row or null
     C.telHref(p)     'tel:' link for one phone entry ({number}), digits only, or null
     C.webLink(row)   the website only when it may be a link (webCheck ok, dialihkan or belum), else null */
(function (C) {
  'use strict';
  if (!C || !C.rows) return;
  var byN = null;
  C.byNpsn = function (npsn) {
    if (!byN) { byN = {}; C.rows.forEach(function (r) { byN[r.npsn] = r; }); }
    return byN[String(npsn)] || null;
  };
  C.telHref = function (p) {
    var d = p && String(p.number || '').replace(/[^0-9+]/g, '');
    return d && d.replace(/\D/g, '').length >= 7 ? 'tel:' + d : null;
  };
  C.webLink = function (row) {
    return row && row.website && (row.webCheck === 'ok' || row.webCheck === 'dialihkan' || row.webCheck === 'belum') ? row.website : null;
  };
})(typeof window !== 'undefined' ? window.MCD_SCHOOL_CONTACTS : undefined);
